			p1: "封面地图是本次审计中最好的一张图。下面说明如何阅读它。",
			p2: "阿尔伯塔被划分为 4,765 个投票区——Elections Alberta 用于点算投票站选票的小地理区域。每一个都按 2023 年其中选民的实际投票情况上色:NDP 票集中的地方为橙色,UCP 票集中的地方为蓝色。但颜色只在大量人口居住的地方才会变深变饱和。一个覆盖数百平方公里草原或农田的投票区会保持淡色——几乎不可见。地图在有人的地方点亮,在没人的地方淡出。",
			p3: "这与你在选举之夜看到的阿尔伯塔非常不同。大多数选举地图根据谁获胜将整个选区涂成纯蓝或纯橙。乡村选区地理面积大,UCP 赢得大多数,所以选举之夜的阿尔伯塔看起来像一片蓝墙,在 Edmonton 和 Calgary 有几个橙色小口袋。封面地图使用相同的选票和相同的地理——但将它们按人们实际居住的位置加权显示。出现的是一个大部分人口集中在密集城市弧线中的省份,而这些城市的投票方式与通常代表它们的乡村地图非常不同。",
