			sub1_close: "多数派地图在四项指标中的三项上稳稳位于正常范围内。它的均值-中位差位于 p1(= p0.99),方向有利于 NDP——这是一个不寻常的结果,但其方向并不能帮助 UCP。多数派地图紧贴市政边界,把 NDP 占多数的城市核心放进各自紧凑的选区;在那里,NDP 的选票以高效的差距获胜,而 UCP 在乡村的胜利往往差距更大。这种轻微的结构性 NDP 效率优势,就是均值-中位指标中显现出来的东西。少数派地图在全部四项上都处于尾部,而且每一项都指向同一个党派方向。",
