			t3_r3_b: "<strong>51.7%(46 席)</strong>",
			t3_r3_c: "<strong>第 99.99 百分位——1,010,000 张中立抽样中不到 100 张达到</strong>",
			sub2_close: "1,010,000 张计算机模拟的中立阿尔伯塔地图中,不到 100 张产生了与少数派提议一样高的 <code>seats@50/50</code> 值。按 2023 年选举日选票,它会给 UCP 60 席(多数派提议为 55 席);按全部选票,是 57 席和 48 席(按保留作为核对的旧提前选票分配方法,是 55 席和 48 席)。多数派提议是中立程序常规产生的那种地图。少数派提议是你必须刻意瞄准才能划出的那种地图。",
			sub3_h: "用通俗语言说明",
			sub3_p: "在四项党派公平性指标中的三项上,少数派提议位于 1,010,000 份方案集合的极端尾部;第四项(效率差,+4.0%)位于第 94.5 百分位——<em>接近但低于</em>审计预先注册的、按阿尔伯塔校准的第 95 百分位阈值。两条联合检验渠道共享底层的效率差数据,在统计上并不独立,因此用 Fisher 方法合并它们的 p 值会高估显著性。依赖性稳健的(Bonferroni)合并给出的模型估计约为<strong>568,000 分之一</strong>(p&nbsp;=&nbsp;1.76×10<sup>−6</sup>)。这仍是一个极端结果,远超常规显著性阈值——但它是一个模型估计,而不是四个独立工具读数一致。",
			details_summary: "这个 p 值意味着什么——以及不意味着什么",
			details_p1: "p 值回答一个问题:如果地图是由中立程序绘制的,我们会多常看到这样极端或更极端的结果?按审计的模型估计 p&nbsp;=&nbsp;1.76×10<sup>−6</sup>,答案是约 568,000 次试验中出现一次。",
			details_p2: "这是一项频率主义假设检验,不是对意图的测量。它并没有说委员会有意进行选区不公划分,也没有量化这份地图在实际意义上有多不公平。它说的是,这种边界模式在统计上与 ReCom 中立绘图参考分布不一致——这是一项有力的外部核查,但并不完美(它没有强制执行委员会工作时所遵循的每一项法定标准,例如 s.15(2) 层级和利益共同体约束)。",
			details_p3: "结构测试包(人口、分割、锚定、紧凑性、签名)已在标准重算之前带时间戳注册(<a href=\"https://osf.io/w2s8k\" rel=\"noopener\">OSF 注册 w2s8k</a>)。党派偏倚渠道(联合 Mahalanobis、SZAT、Fisher/Bonferroni 组合)按审计自身 §4.3.1 的意义被标记为\"探索性\":记录在版本库中,但并非数据前预先注册。审计分别报告每条渠道,并以 Bonferroni 翻倍的方式将它们合并,而非将它们呈现为完全独立的确证测试。",
			szat_label: "摆动区分配测试(SZAT)",
			szat_body: "SZAT 被设计为第二条分析渠道:它不问\"这份地图整体上是否极端?\",而是问\"那些具体的划线选择是否党派中立?\"。它的做法是只挑出少数派地图与多数派地图不同的那些投票区——即有争议的重绘——并检验这些特定选择合在一起是否将选票效率朝某一党的方向移动。由于它只比较分歧之处,它自动控制了两份地图共有的一切:相同的地理、人口目标和法定规则。在标准置换检验下 SZAT 返回 p=0.0024;在校正了相邻投票区之间空间自相关的分块置换零假设下,它返回 p≈0.19——不显著。SZAT 作为探索性背景保留,但作为确证渠道并不成立。结论仅依赖于模拟本身。<a href=\"https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json\" rel=\"noopener\">技术细节 →</a>",
			two_q: "<strong>SZAT 结果。</strong>1,010,000 张地图的模拟问的是:<em>与在同一阿尔伯塔地理上绘制的中立地图相比,这份地图是否极端?</em>第二项测试——<a href=\"https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json\" rel=\"noopener\">摆动区分配测试</a>——问的是另一个问题:<em>地图上那些具体的线条是否党派中立?</em>它的做法是只看少数派与多数派划得不同的投票区,并询问这些特定选择合在一起,是否把选票效率推向了某一党的方向。在标准置换下,它得出 p=0.0024。在分块置换零假设下——它校正了相邻投票区之间的空间自相关——它得出 p≈0.19。分块置换结果没有达到显著。因此,审计只把模拟结果作为主要结论:经 Bonferroni 校正的模型估计为 <strong>568,000 分之 1</strong>(p&nbsp;=&nbsp;1.76×10<sup>−6</sup>),而不是两个独立渠道的 Fisher 合并。",
			super_lead: "在一个 89 席的立法机关中,三分之二的超级多数恰好需要 60 席。少数派提议在平票时的议席份额为 51.7%——1,010,000 张中立地图中只有 69 张达到这个水平——它处在 UCP 超级多数在阿尔伯塔 2023 年地理上于统计上变得可以达到的区间。但模拟并没有强制执行委员会工作时所遵循的每一项法定标准,因此这是一项有力的外部核查,而不是\"没有任何合法合规的阿尔伯塔地图能达到这一议席数\"的证明。第一幕中的结构性证据完全不依赖模拟,承担了大部分分量;平票时的尾部位置是支撑性的背景。",
			super_label: "为什么庞大多数重要",
			super_body: "在加拿大威斯敏斯特制度下,阿尔伯塔议会并不存在解锁特殊权力的三分之二门槛:执政多数——哪怕仅勉强过半——便已能通过法律和预算、援引\"截止辩论\"以结束辩论、改变议会规则,并确定每个委员会的成员构成。庞大多数所改变的是优势幅度和稳固程度,而非可用权力的菜单。在 89 席中持有 60 席的政府实际上不受内部异议的影响——少数几位议员跨党转投都无法对其构成威胁——并且其面对的反对派太小,无法强制进行记名表决或维持委员会监督。这里所关切的是席位的集中和有效反对派的削弱,而非跨越了某个程序性门槛。",
			super_close: "第一幕中识别出的城市混合模式——城市选民被分散进周围的乡村边缘选区——与 60 席的结果相符;不过,审计直接检验\"这种几何形态是否就是具体机制\"的测试,无法在其最终数据上进行(发现 9)。结构性发现和统计性发现汇合在同一份提议、同一些社区上——而且在谁受益这一点上是一致的。",
			sub4_h: "来自定向程序测试的确认",
			sub4_p: "为了确保这不是中立模拟已知紧凑性偏好的怪癖,审计在两个方向上运行了定向爬山程序(<a href=\"https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md\" rel=\"noopener\">Cannon 等人 2022 年——在技术报告中引用并描述</a>):最大化 UCP 议席与最大化 NDP 议席。每个方向相同的步数(40,000),相同的法定约束,相同的省级几何。",
			t4_col_a: "程序",
