			t4_r1_a: "中立 MCMC,产生的最大值",
			t4_r1_b: "50/50 时 UCP 议席 51.72%(1,010,000 个方案中有 69 个超过少数派的 51.69%)",
			t4_r1_c: "中立绘图下的自然上限",
			t4_r2_a: "中立 MCMC,产生的最小值",
			t4_r2_b: "@ 50/50 下约 39% UCP 议席",
			t4_r2_c: "中立绘图下的自然下限",
