			c5_cond: "背景:2026 年 4 月 22 日——阿尔伯塔通过政府第 37 号动议的次日——加拿大最高法院以 7 比 2 当庭裁决维持魁北克上诉法院的裁决,即 Legault 政府对其选区重划委员会的立法冻结违反了《宪章》第 3 条民主代表权保障。条件:审查阿尔伯塔动议的法院发现它在宪法上有所不同——例如,将工作重新分配给 MLA 委员会与立法冻结在结构上不同,或阿尔伯塔在第 3 条下的有效代表权分析与魁北克的不同。",
