				p1: "设想一个 40,000 人的镇,大多投给橙党。它周围的地区大多投给蓝党。给这个镇一个自己的选区(选出一位 MLA 的区域),它就会选出一位橙党 MLA。这就是 40,000 人、一个议席、一个声音。现在把这个镇切成四块。把每一块都与一片投蓝党的乡村合在一起。在每个新选区里,10,000 名镇上的选民面对 30,000 名农村选民。橙党四个全输。同样的选民,同样的选票,没有议席。没有哪一位选民失去了什么。<em>这个镇</em>失去的,是选出任何人的能力。这就是分散。它的反面是集中(附录 C):把一个群体塞进尽可能少的选区,让它在那些选区以巨大优势获胜,其他地方一无所获。",
