				p2: "计算机一次只走一小步。它取两个共享边界的选区,把它们合并成一个。然后它随机地把这个区域分成两个新的合法选区。它这样重复 1,010,000 次,并在每一步之后保存地图。这种方法叫作 ReCom。它是这一领域的标准工具。",
				p3: "关键事实是:<strong>计算机从不看任何选票。</strong>它不知道 UCP 或 NDP 的选民住在哪里。本网站称这些地图为中立,只是在这个意义上。所以,如果一张计算机绘制的地图仍然偏向一方,这种倾向来自阿尔伯塔人住在哪里以及那两条规则。如果一份真实地图比几乎所有这些地图都偏得远得多,那么单凭地理和规则就很难解释了。",
