				li3: "<strong>关于议席数的说明。</strong>委员会的两份地图各有 89 个选区。计算机绘制的地图有 87 个,也就是 2019 年地图的规模,那是最近一份通过成为法律的地图。咨询小组的地图有 91 个。所以本网站以<em>份额</em>来给出议席,这让三种规模可以并排比较。这种对应很接近,但不精确。我给这些跨规模的比较加了标注,并用同样规模的计算机绘制地图来核对它们。这些同样规模的结果是临时的。",
