				li1: "<strong>1. 人口分布。</strong>选区偏离理想规模有多远?按委员会自己的表格,多数派地图的选区平均偏离 3,180 人。少数派地图的平均偏离 4,707 人,大约多出一半。偏离越大,意味着选票越不平等。不过按 2021 年人口普查数字,三份地图的平均偏离几乎相同。",
				li2: "<strong>2. Calgary 的拥挤程度。</strong>在 Calgary 东北部和中部,少数派地图的选区比全省平均数多 11.5% 的人口。多数派地图的多 2.8%。(如果按这个区域所陈述的地理规则的字面意思来读,数字是 8.5% 到 8.9%,以及 1.3% 到 1.6%。)在更大的选区里,每一票的分量更轻。把一个政党的选民塞进更少、更大的选区,叫作<em>集中</em>。但我的集中测试在这里没有检测到它:按 2023 年的选票,NDP 赢下这个区域十七个选区中的八个,胜幅都低于全省平均水平。",
				li3: "<strong>3. Airdrie 的拆分。</strong>法律要求 Airdrie 至少有两个选区。多数派地图用了两个。少数派地图把这座城市切成四块(其中三块至少有其 2% 的人口),每一块都与城外不同的土地合在一起。把一个社区分得很零碎,叫作<em>分散</em>。这次拆分越过了这项测试的界线。它没有越过我另外那项分散测试的界线,而那项测试是探索性的:Airdrie East 把这座城市一半以上的人保持在一起,而它的人口中有九成住在 Airdrie。",
