				li1: "<strong>1. 50 比 50 测试。</strong>把每个选区的得票都移动同样的幅度,直到全省正好 50 比 50,然后数每个政党的议席。在阿尔伯塔,一张典型的计算机绘制地图在平票时给 UCP 44.8% 的议席,因为 UCP 在农村的胜幅比 NDP 在城市的胜幅更大。多数派地图给 UCP 46.1%:第 78 百分位,很普通。2019 年地图给 46.0%:第 65 百分位(或者按最初登记的方式,如果把与它持平的每张地图都算在它下面,则是第 78 百分位)。少数派地图给 UCP <strong>51.7%</strong>(89 席中的 46 席),在平票时取得多数议席。1,010,000 张计算机绘制的地图中只有 69 张给 UCP 更多。作为参照,一种被要求<em>刻意</em>为 UCP 赢得尽可能多议席的方法,在一次设定了种子的运行中达到了 52.9%(87 席中的 46 席)。没有任何证据表明这就是可能达到的最高值。",
				li2: "<strong>2. 效率差。</strong>每一张选票要么有助于赢得一个议席,要么就是\"浪费\"的:投给了落选者,或者堆在胜选者身上,超出了获胜所需。这项指标比较两党浪费的选票。差距为正有利于 UCP。多数派地图得分 +0.1%,接近于零。少数派地图得分 +4.0%,位于第 94.5 百分位。这刚好<em>低于</em>我事先设定的界线,即第 95 百分位(约 +4.1%)。这是唯一没有被标记的指标,我把它报告为未达到。",
				li3: "<strong>3. 均值-中位差。</strong>比较一个政党在各选区的平均结果与居中选区的结果。当两者拉开距离时,就说明选票在某处被集中成了大胜。少数派地图的差距比 99.97% 的计算机绘制地图更有利于 UCP。多数派地图的差距偏向另一方向,即偏向 NDP,比其中 99% 的地图偏得更远。我也报告了这个异常值。我对它没有经过检验的解释。",
